/// Finisher (Silent Uncommon Attack, 1 energy, AnyEnemy). C#
/// `Finisher.cs` (v0.103.2): `CalculatedHits = 0 + 1 ×
/// prior_attack_plays_this_turn` (from
/// `History.CardPlaysFinished` filtered to player Attack plays,
/// EXCLUDING the in-flight Finisher itself). So hits = N prior
/// attacks; if N=0 the attack lands 0 hits (`WithHitCount(0)`).
///
/// Damage is rolled per-hit through `deal_damage_player_to_enemy`
/// so Strength / Vulnerable / Weak / etc. fire once per hit.
///
/// History:
/// - `sts2-rs-txm8` ported the per-turn Attack counter but added
///   `(prior + 1).max(1)` matching Python's `max(1, ...)` fallback
///   — a Python-pin drift the C# decomp does NOT share.
/// - `sts2-rs-nucbp` removed the `+1` self-hit and the `.max(1)`
///   floor; tests updated to assert 0 hits on N=0 and N hits
///   otherwise.
pub(crate) fn play_finisher(state: &mut CombatState, target: Option<CreatureUid>) -> EffectResult {
    let t = target.expect("Finisher: Enemy-targeted");
    // Bead `sts2-rs-nucbp`: C# `Finisher.cs` (v0.103.2) is
    // `CalculationBase(0) + CalculationExtra(1) × prior_attacks`,
    // i.e. hits = prior attacks this turn (Finisher itself is
    // in-flight and NOT counted by `History.CardPlaysFinished`;
    // the per-turn bucket is also bumped AFTER this dispatch). The
    // prior `(prior+1).max(1)` body added a phantom self-hit AND
    // floored output at 1 when C# `WithHitCount(0)` deals 0 hits.
    let hits = resolving_preview(state, preview_finisher, target);
    let base = current_card_damage(state);
    for _ in 0..hits {
        let _ = deal_damage_player_to_enemy(state, t, base);
    }
    EffectResult::Resolved
}

